// Letakkan kode verifikasi Google Search Console di sini.
// Contoh:
//   <meta name="google-site-verification" content="XXXXX" />
//
// Kode ini akan otomatis ditambahkan ke semua halaman HTML
// (landing page, QR viewer, 404, dll.) tetapi TIDAK ke endpoint API.
//
// Setelah daftar di Google Search Console, tempel kode di bawah ini:
// ─────────────────────────────────────────────────────────────────────────
const GSC_VERIFICATION_META = '';
// ═══════════════════════════════════════════════════════════════════════════

// Osu! Panel — Cloudflare Worker
// Environment: https://osu-panel.zhyllanfyllah.my.id
//
// This worker holds the osu! Client ID + Secret and issues tokens to the
// app (Flutter / native Android). The app never sees the Client Secret.
//
// ── CONFIGURATION (Worker settings → Variables & Secrets) ──
//   CLIENT_ID     = "65842"            (var)
//   CLIENT_SECRET = "<osu! secret>"    (secret — hidden)
//
// The secret MUST live in the CLIENT_SECRET environment variable — there is
// intentionally NO fallback secret in this file (public repository).
const FALLBACK_CLIENT_ID = '65842';
const FALLBACK_CLIENT_SECRET = '';

const OS_TOKEN_URL = 'https://osu.ppy.sh/oauth/token';

// Redirect URIs allowed to exchange a code (must match exactly the osu!
// callback registered for the application). Defense in depth — osu! also
// validates it.
const FALLBACK_ALLOWED_REDIRECT_URIS = ['osupanel://callback'];

// Rate limit: 30 requests / 60 seconds per IP for every /auth/* endpoint.
const RATE_LIMIT_MAX = 30;
const RATE_LIMIT_WINDOW_MS = 60_000;

// ── Token cache (client_credentials) ──
// Client-credentials tokens are NOT user-specific and can be shared across
// all requests. Cache them to avoid hitting the osu! token endpoint on
// every single QR scan or beatmap fetch.
let _ccToken = null;
let _ccTokenExpiry = 0;
const TOKEN_CACHE_TTL_MS = 50 * 60 * 1000; // 50 min (osu! tokens live 1h)

// ── Beatmap cache (in-memory, per-isolate) ──
// Avoids fetching the same beatmapset from osu! on every QR scan.
const beatmapCache = new Map();
const BEATMAP_CACHE_TTL_MS = 10 * 60 * 1000; // 10 minutes

// ── CORS (kept: useful when testing from a browser) ──
const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
};

const TOKEN_CACHE_HEADERS = { 'Cache-Control': 'no-store' };

// ── Helper: inject GSC meta tag into HTML pages ──
function injectGscMeta(html) {
  if (!GSC_VERIFICATION_META) return html;
  return html.replace('</head>', GSC_VERIFICATION_META + '\n</head>');
}

// ── Helper: robots.txt content ──
function robotsTxt() {
  const lines = [
    'User-agent: *',
    'Allow: /',
    'Disallow: /auth/',
    'Disallow: /health',
    '',
    'Sitemap: https://osu-panel.zhyllanfyllah.my.id/sitemap.xml',
    '',
  ];
  return lines.join('\n');
}

// ── Helper: sitemap.xml content ──
function sitemapXml() {
  const base = 'https://osu-panel.zhyllanfyllah.my.id';
  const now = new Date().toISOString().split('T')[0];
  const pages = [
    { loc: '/', priority: '1.0', changefreq: 'weekly' },
    { loc: '/qr', priority: '0.7', changefreq: 'monthly' },
  ];
  const urls = pages.map((p) => `
  <url>
    <loc>${base}${p.loc}</loc>
    <lastmod>${now}</lastmod>
    <changefreq>${p.changefreq}</changefreq>
    <priority>${p.priority}</priority>
  </url>`).join('');
  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls}
</urlset>`;
}

// ── Helper: clean 404 page (nginx-style white) ──
function notFoundPage() {
  return `<!DOCTYPE html>
<html>
<head>
<title>404 Not Found</title>
<link rel="icon" type="image/x-icon" href="data:image/x-icon;base64,">
</head>
<body>
<center><h1>404 Not Found</h1></center>
<hr><center>nginx</center>
</body>
</html>`;
}

