function decodeB64(h) {
  try {
    let b = h.replace(/-/g, '+').replace(/_/g, '/');
    while (b.length % 4) b += '=';
    return JSON.parse(decodeURIComponent(escape(atob(b))));
  } catch (e) {
    return null;
  }
}

// Fetch beatmap data from osu! API by ID
async function getClientCredentialsToken(env) {
  const now = Date.now();
  if (_ccToken && now < _ccTokenExpiry) return _ccToken;

  const tokenParams = new URLSearchParams();
  tokenParams.append('client_id', getClientId(env));
  tokenParams.append('client_secret', getClientSecret(env));
  tokenParams.append('grant_type', 'client_credentials');
  tokenParams.append('scope', 'public');

  const tokenResp = await fetch(OS_TOKEN_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      Accept: 'application/json',
    },
    body: tokenParams.toString(),
  });

  if (!tokenResp.ok) throw new Error('Token fetch failed: ' + tokenResp.status);

  const tokenData = await tokenResp.json();
  _ccToken = tokenData.access_token;
  _ccTokenExpiry = now + TOKEN_CACHE_TTL_MS;
  return _ccToken;
}

function renderQrViewerPage(data) {
  return new Response(injectGscMeta(buildOgHtml(data)), {
    headers: {
      'Content-Type': 'text/html;charset=UTF-8',
      'Cache-Control': 'public, max-age=300',
    },
  });
}

function renderQrViewerFallback() {
  return new Response(injectGscMeta(QR_VIEWER_HTML), {
    headers: { 'Content-Type': 'text/html;charset=UTF-8' },
  });
}

async function buildBeatmapData(beatmapsetId, env) {
  const now = Date.now();
  const cached = beatmapCache.get(beatmapsetId);
  if (cached && now < cached.expiry) return cached.data;

  const accessToken = await getClientCredentialsToken(env);
  const bmsResp = await fetch(`https://osu.ppy.sh/api/v2/beatmapsets/${beatmapsetId}`, {
    headers: { Authorization: `Bearer ${accessToken}`, Accept: 'application/json' },
  });
  if (!bmsResp.ok) throw new Error('Beatmap fetch failed: ' + bmsResp.status);

  const bms = await bmsResp.json();
  const bm = (bms.beatmaps && bms.beatmaps[0]) || {};
  const cover = (bms.covers && (bms.covers['cover@2x'] || bms.covers.cover))
    || `https://assets.ppy.sh/beatmaps/${beatmapsetId}/covers/list.jpg`;
  const mode = bm.mode || 'osu';
  const osuUrl = `https://osu.ppy.sh/beatmapsets/${beatmapsetId}#${mode}/${bm.id || ''}`;

  function fmtDuration(s) {
    if (!s) return '0:00';
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return m + ':' + (sec < 10 ? '0' : '') + sec;
  }

  const data = {
    title: bms.title || '',
    artist: bms.artist || '',
    mapper: bms.creator || '',
    bpm: bms.bpm || 0,
    length: fmtDuration(bm.total_length),
    cover,
    url: osuUrl,
    tags: bms.tags || '',
    preview: bms.preview_url || '',
  };

  beatmapCache.set(beatmapsetId, { data, expiry: Date.now() + BEATMAP_CACHE_TTL_MS });
  return data;
}

async function handleQrBeatmapIdJson(beatmapsetId, env) {
  const data = await buildBeatmapData(beatmapsetId, env);
  return json(data, 200, { 'Cache-Control': 'public, max-age=300' });
}

async function handleQrBeatmapId(beatmapsetId, env) {
  try {
    const data = await buildBeatmapData(beatmapsetId, env);
    return renderQrViewerPage(data);
  } catch {
    return renderQrViewerFallback();
  }
}

function buildOgHtml(data) {
  const title = data.title || 'Beatmap';
  const artist = data.artist || '';
  const mapper = data.mapper || '';
  const bpm = data.bpm || '';
  const length = data.length || '';
  const tags = data.tags || '';
  const cover = data.cover || '';
  const desc = [
    mapper ? 'by ' + mapper : '',
    bpm ? 'BPM ' + bpm : '',
    length ? length : '',
    tags ? tags.split(',').slice(0, 5).join(', ') : '',
  ].filter(Boolean).join(' | ');

  const ogTags =
    '<meta property="og:title" content="' + title + ' — ' + artist + ' | Osu! Panel">\n' +
    '<meta property="og:description" content="' + desc + '">\n' +
    '<meta property="og:type" content="music.song">\n' +
    '<meta property="og:site_name" content="Osu! Panel">\n' +
    (cover ? '<meta property="og:image" content="' + cover + '">\n' : '') +
    '<meta name="twitter:card" content="summary">\n' +
    '<meta name="twitter:title" content="' + title + ' — ' + artist + '">\n' +
    '<meta name="twitter:description" content="' + desc + '">\n' +
    (cover ? '<meta name="twitter:image" content="' + cover + '">\n' : '') +
    '<meta name="theme-color" content="#E86E9E">\n' +
    '<title>' + title + ' — ' + artist + ' | Osu! Panel</title>';

  return QR_VIEWER_HTML
    .replace('<title>Osu! Panel — QR Beatmap Viewer</title>', ogTags)
    .replace(
      'if(!tryParam()&&!tryHash())startCam();',
      'showData(' + JSON.stringify(data) + ');'
    );
}

function json(data, status = 200, extraHeaders = {}) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...CORS_HEADERS, ...extraHeaders, 'Content-Type': 'application/json' },
  });
}

/** Token response — must never be cached by a browser/proxy. */
function jsonToken(data, status = 200) {
  return json(data, status, TOKEN_CACHE_HEADERS);
}

function getClientId(env) {
  return env?.CLIENT_ID || FALLBACK_CLIENT_ID;
}

function getClientSecret(env) {
  return env?.CLIENT_SECRET || FALLBACK_CLIENT_SECRET;
}

function getAllowedRedirectUris(env) {
  const raw = env?.ALLOWED_REDIRECT_URI;
  if (raw) return raw.split(',').map((s) => s.trim()).filter(Boolean);
  return FALLBACK_ALLOWED_REDIRECT_URIS;
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// ── Fetch an osu! token with retry for transient errors ──
// osu! can answer 429 (rate limit — the CODE IS NOT USED, safe to retry)
// or a brief 5xx. A short retry with backoff + honoring `Retry-After` makes
// one-tap login much more robust. Permanent errors (400/401 invalid_grant,
// etc.) are passed through as-is.
async function fetchOsuToken(params, attempts = 3) {
  let delayMs = 400;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    const resp = await fetch(OS_TOKEN_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        Accept: 'application/json',
      },
      body: params.toString(),
    });

    // Success, permanent error, or last attempt → return as-is.
    const transient = resp.status === 429 || resp.status >= 500;
    if (resp.ok || !transient || attempt === attempts) return resp;

    const retryAfterSec = Number(resp.headers.get('Retry-After'));
    const waitMs = retryAfterSec > 0 ? retryAfterSec * 1000 : delayMs;
    await sleep(waitMs);
    delayMs *= 2;
  }
  // Unreachable — the loop always returns on the last attempt.
}

// ── Per-IP rate limiter (in-memory, sliding window) ──
// Note: this Map is per-isolate — enough to curb light abuse.
const rateHits = new Map();

function isRateLimited(request) {
  const ip = request.headers.get('CF-Connecting-IP');
  if (!ip) return false;

  const now = Date.now();
  const cutoff = now - RATE_LIMIT_WINDOW_MS;
  const timestamps = (rateHits.get(ip) || []).filter((t) => t > cutoff);

  if (timestamps.length >= RATE_LIMIT_MAX) {
    rateHits.set(ip, timestamps);
    return true;
  }

  timestamps.push(now);
  rateHits.set(ip, timestamps);
  return false;
}

// ── Read a JSON body safely → null when malformed ──
async function readJsonBody(request) {
  try {
    return await request.json();
  } catch {
    return null;
  }
}

// ── POST /auth/code — Exchange an OAuth code for user tokens ──
async function handleAuthCode(request, env) {
  const body = await readJsonBody(request);
  const code = body?.code;
  const redirectUri = body?.redirect_uri;
  const codeVerifier = body?.code_verifier;

  if (!code || !redirectUri) {
    return json({ error: 'Missing code or redirect_uri' }, 400);
  }

  if (!getAllowedRedirectUris(env).includes(redirectUri)) {
    return json({ error: 'redirect_uri not allowed' }, 400);
  }

  const params = new URLSearchParams();
  params.append('client_id', getClientId(env));
  params.append('client_secret', getClientSecret(env));
  params.append('grant_type', 'authorization_code');
  params.append('code', code);
  params.append('redirect_uri', redirectUri);
  // PKCE (RFC 7636): osu! requires the code_verifier when exchanging a code.
  // Only forwarded when valid (43–128 unreserved chars) — a bad verifier is
  // rejected by osu! anyway, no need to forward it as-is.
  if (typeof codeVerifier === 'string' && codeVerifier.length >= 43 && codeVerifier.length <= 128) {
    params.append('code_verifier', codeVerifier);
  }

  const tokenResp = await fetchOsuToken(params);

  const data = await tokenResp.json().catch(() => null);
  if (!tokenResp.ok) {
    return jsonToken(
      { error: 'Failed to exchange code' },
      tokenResp.status,
    );
  }

  return jsonToken({
    access_token: data.access_token,
    refresh_token: data.refresh_token ?? null,
    expires_in: data.expires_in,
    token_type: data.token_type ?? 'Bearer',
  });
}

// ── POST /auth/refresh — Refresh an access token ──
async function handleAuthRefresh(request, env) {
  const body = await readJsonBody(request);
  const refreshToken = body?.refresh_token;

  if (!refreshToken) {
    return json({ error: 'Missing refresh_token' }, 400);
  }

  const params = new URLSearchParams();
  params.append('client_id', getClientId(env));
  params.append('client_secret', getClientSecret(env));
  params.append('grant_type', 'refresh_token');
  params.append('refresh_token', refreshToken);
  // Note: scope is NOT sent — the refresh token carries the original grant's
  // scope; sending scope can trigger a scope-mismatch error on some servers.

  const tokenResp = await fetchOsuToken(params);

  const data = await tokenResp.json().catch(() => null);
  if (!tokenResp.ok) {
    return jsonToken(
      { error: 'Failed to refresh token' },
      tokenResp.status,
    );
  }

  return jsonToken({
    access_token: data.access_token,
    refresh_token: data.refresh_token ?? refreshToken,
    expires_in: data.expires_in,
    token_type: data.token_type ?? 'Bearer',
  });
}

// ── POST /auth/token — Client credentials token (quick login / identifier) ──
async function handleAuthToken(request, env) {
  const body = await readJsonBody(request);
  const identifier = body?.identifier;

  if (!identifier) {
    return json({ error: 'Missing identifier' }, 400);
  }

  // NOTE: a client credentials token is NOT user-specific; `identifier` is
  // only forwarded so the app knows which user to fetch afterwards.
  const params = new URLSearchParams();
  params.append('client_id', getClientId(env));
  params.append('client_secret', getClientSecret(env));
  params.append('grant_type', 'client_credentials');
  params.append('scope', 'public');

  const tokenResp = await fetchOsuToken(params);

  if (!tokenResp.ok) {
    return jsonToken(
      { error: 'Failed to get osu! token' },
      tokenResp.status,
    );
  }

  const tokenData = await tokenResp.json();
  return jsonToken({
    access_token: tokenData.access_token,
    expires_in: tokenData.expires_in,
    token_type: tokenData.token_type,
    identifier: identifier,
  });
}

// ── GET /auth/diag — Diagnostics (troubleshooting only) ──
// Reports which client id the worker actually uses (env vs fallback) plus
// the result of ONE token probe to osu! (no retry), so it is clear whether
// these credentials are accepted from the worker's egress IP.
async function handleDiag(request, env) {
  try {
    const probe = new URLSearchParams();
    probe.append('client_id', getClientId(env));
    probe.append('client_secret', getClientSecret(env));
    probe.append('grant_type', 'client_credentials');
    probe.append('scope', 'public');

    const started = Date.now();
    const resp = await fetch(OS_TOKEN_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        Accept: 'application/json',
      },
      body: probe.toString(),
    });
    const ms = Date.now() - started;
    const body = (await resp.text().catch(() => ''))
      .replace(/("access_token"\s*:\s*")[^"]+/, '$1MASKED');

    return json({
      clientId: getClientId(env),
      clientIdSource: env?.CLIENT_ID ? 'env' : 'fallback',
      secretSource: env?.CLIENT_SECRET ? 'env' : 'fallback',
      osuProbe: { status: resp.status, ms, body: body.slice(0, 200) },
    });
  } catch (e) {
    return json({ error: 'Diag probe failed' }, 500);
  }
}

// ── Main ──
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    // Normalize trailing slash (/auth/code/ == /auth/code)
    const path = url.pathname.replace(/\/+$/, '') || '/';
    const method = request.method;

    // CORS preflight
    if (method === 'OPTIONS') {
      return new Response(null, { headers: CORS_HEADERS });
    }

    // Rate limit only the auth endpoints (prevent token spam)
    if (path.startsWith('/auth/')) {
      if (isRateLimited(request)) {
        return json({ error: 'Too many requests, try again later' }, 429);
      }
    }

    if (path === '/auth/code' && method === 'POST') {
      return handleAuthCode(request, env).catch(() =>
        json({ error: 'Internal error' }, 500),
      );
    }

    if (path === '/auth/refresh' && method === 'POST') {
      return handleAuthRefresh(request, env).catch(() =>
        json({ error: 'Internal error' }, 500),
      );
    }

    if (path === '/auth/token' && method === 'POST') {
      return handleAuthToken(request, env).catch(() =>
        json({ error: 'Internal error' }, 500),
      );
    }

    if (path === '/auth/diag' && method === 'GET') {
      return handleDiag(request, env);
    }

    // ── robots.txt ──
    if (path === '/robots.txt' && method === 'GET') {
      return new Response(robotsTxt(), {
        headers: {
          'Content-Type': 'text/plain;charset=UTF-8',
          'Cache-Control': 'public, max-age=86400',
        },
      });
    }

    // ── sitemap.xml ──
    if (path === '/sitemap.xml' && method === 'GET') {
      return new Response(sitemapXml(), {
        headers: {
          'Content-Type': 'application/xml;charset=UTF-8',
          'Cache-Control': 'public, max-age=86400',
        },
      });
    }

    // Landing page (root)
    if (path === '/' && method === 'GET') {
      return new Response(injectGscMeta(LANDING_HTML), {
        headers: {
          'Content-Type': 'text/html;charset=UTF-8',
          'Cache-Control': 'public, max-age=3600',
        },
      });
    }

    // Health check
    if (path === '/health' && method === 'GET') {
      return json({ status: 'ok', service: 'osu-panel-worker' });
    }

    // ── Public config (client_id for OAuth) ──
    if (path === '/auth/config' && method === 'GET') {
      return json({ client_id: getClientId(env) });
    }

    // ── QR Beatmap by ID (short link: /qr/12345) ──
    const qrIdMatch = path.match(/^\/qr\/(\d+)$/);
    if (qrIdMatch && method === 'GET') {
      return handleQrBeatmapId(parseInt(qrIdMatch[1]), env).catch(() =>
        new Response(injectGscMeta(QR_VIEWER_HTML), {
          headers: { 'Content-Type': 'text/html;charset=UTF-8' },
        }),
      );
    }

    // ── QR Beatmap JSON (for AJAX fetch from the scanner page) ──
    const qrJsonMatch = path.match(/^\/qr\/data\/(\d+)$/);
    if (qrJsonMatch && method === 'GET') {
      return handleQrBeatmapIdJson(parseInt(qrJsonMatch[1]), env).catch(() =>
        json({ error: 'Failed to fetch beatmap' }, 500),
      );
    }

    // ── QR Beatmap Viewer ──
    if (path === '/qr' && method === 'GET') {
      const dParam = url.searchParams.get('d');
      if (dParam) {
        const data = decodeB64(dParam);
        if (data && data.title) {
          const html = injectGscMeta(buildOgHtml(data));
          return new Response(html, {
            headers: {
              'Content-Type': 'text/html;charset=UTF-8',
              'Cache-Control': 'public, max-age=3600',
            },
          });
        }
        // Invalid base64 → redirect to clean page
        return Response.redirect(url.origin + '/qr', 302);
      }
      // No data → serve normal viewer (camera scanning)
      return new Response(injectGscMeta(QR_VIEWER_HTML), {
        headers: {
          'Content-Type': 'text/html;charset=UTF-8',
          'Cache-Control': 'public, max-age=300',
        },
      });
    }

    // ── 404 (clean nginx-style white page) ──
    return new Response(notFoundPage(), {
      status: 404,
      headers: { 'Content-Type': 'text/html;charset=UTF-8' },
    });
  },
};
